  const root=this.shadowRoot;
  for(const [view,label] of [['home','For you'],['library','Shows'],['films','Films'],['live','Live TV']])root.querySelector('nav').append(this.button(label,()=>{this.view=view;this.genre='';this.query='';root.querySelector('.search').value='';this.heroIndex=0;this.browseKey=null;this.paint();this.snapshot();this.loadBrowse()},view));
