  root.querySelector('.search').oninput=e=>{this.query=e.target.value;this.paintContent();clearTimeout(this.searchTimer);this.searchTimer=setTimeout(()=>this.loadBrowse(),350)};root.querySelector('.genre-filter').onchange=e=>{this.genre=e.target.value;this.browseKey=null;this.paintContent();this.loadBrowse()};
