  const slider=root.querySelector('.browser-timeline');slider.onpointerdown=()=>{this.pointerScrub=true;this.showControls(true);root.querySelector('video').pause()};slider.oninput=()=>{this.previewPosition=Number(slider.value);this.paintBrowserTime()};slider.onchange=()=>{if(this.pointerScrub){this.pointerScrub=false;this.seekBrowser(Number(slider.value))}};
